output_shape_driver:
use std::path::Path;
use symbolica::atom::{Atom, AtomView};
fn leaves(value: AtomView<'_>) -> usize {
    match value {
        AtomView::Add(sum) => sum.iter().map(leaves).sum(),
        AtomView::Mul(product) => product.iter().map(leaves).product(),
        _ => 1,
    }
}
fn main() {
    idenso::representations::initialize();
    for phase in ["before", "after"] {
        let directory = Path::new("/tmp/trace-order-improvements").join(format!("{phase}-output"));
        let mut paths: Vec<_> = std::fs::read_dir(directory).unwrap().map(|p| p.unwrap().path()).filter(|p| p.to_string_lossy().ends_with(".full_gamma.output")).collect();
        paths.sort();
        for path in paths {
            let input = std::fs::read_to_string(&path).unwrap();
            let atom = Atom::parse(&input, "spenso", symbolica::parser::ParseSettings::symbolica()).unwrap();
            let case = path.file_name().unwrap().to_str().unwrap().strip_suffix(".full_gamma.output").unwrap();
            println!("{{\"phase\":{phase:?},\"case\":{case:?},\"top_terms\":{},\"arithmetic_leaves\":{}}}", atom.nterms(), leaves(atom.as_view()));
        }
    }
}

